// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1 ether, 100 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        bool ok1;
        try c.withdrawAll() { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1, "first withdraw should succeed");

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        bool ok2;
        try c.withdrawAll() { ok2 = true; } catch { ok2 = false; }

        // General rule: the lock is always released, so a second full
        // withdraw cycle (deposit then withdrawAll) must also succeed.
        assertTrue(ok2, "second withdrawAll must succeed after re-deposit");
    }
}
